#include <linux/sched.h>
#include <linux/cred.h>
#include <linux/audit.h>

int set_apparmor_process_attr(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0 || !name || !value) {
        return -EINVAL;
    }

    if (!task) {
        task = current;
    }

    if (!task->cred || !has_cap_effective(task, CAP_SYS_ADMIN)) {
        return -EPERM;
    }

    if (!strchr(name, '\0') || !strchr(value, '\0')) {
        return -EFAULT;
    }

    if (strcmp(name, "aa_profile") == 0) {
        return set_apparmor_profile(task, value);
    } else if (strcmp(name, "aa_namespace") == 0) {
        return set_apparmor_namespace(task, value);
    } else {
        audit_log_untrusted_string(name);
        return -EINVAL;
    }

    return (int)size;
}

int set_apparmor_task_attribute(struct task_struct *task, char *name, void *value, size_t size) {
    if (size == 0 || name == NULL || value == NULL) {
        return -EINVAL;
    }

    if (!task_is_owner(task)) {
        return -EPERM;
    }

    if (strcmp(name, "profile") == 0) {
        int ret = set_apparmor_profile(task, value);
        if (ret < 0) {
            audit_log_unrecognized_attribute(name);
            return ret;
        }
    } else if (strcmp(name, "label") == 0) {
        int ret = set_apparmor_label(task, value);
        if (ret < 0) {
            audit_log_unrecognized_attribute(name);
            return ret;
        }
    } else {
        audit_log_unrecognized_attribute(name);
        return -EINVAL;
    }

    return size;
}

#include <linux/sched.h>
#include <linux/audit.h>
#include <linux/err.h>
#include <linux/uaccess.h>

int aa_setprocattr(struct task_struct *task, char *name, void *value, size_t size)
{
    int error;

    if (size == 0)
        return -EINVAL;

    if (value == NULL)
        return -EFAULT;

    if (!is_valid_string(name, AA_NAMELEN) || !is_valid_string(name, AA_NAMELEN))
        return -EINVAL;

    if (!current->cred->cap_effective || !has_perm(current_cred(), CAP_SYS_ADMIN))
        return -EPERM;

    if (strcmp(name, "profile") == 0) {
        error = aa_set_profile(task, value, size);
        if (error < 0)
            return error;
    } else if (strcmp(name, "namespace") == 0) {
        error = aa_set_namespace(task, value, size);
        if (error < 0)
            return error;
    } else {
        audit_log(audit_context(), GFP_KERNEL, AUDIT_AA_DENIED,
                  "aa_setprocattr", "unknown attribute name", name, NULL);
        return -EINVAL;
    }

    return size;
}
